import 'dart:io';

import 'package:flutter/services.dart';

import '../core/app_palette.dart';

/// Switches the iOS home-screen icon to match the chosen palette.
///
/// Each non-default palette has an alternate icon set,
/// `AppIcon-<palette name>`, generated by `tool/mascot/mascot.py` and listed
/// under `ASSETCATALOG_COMPILER_ALTERNATE_APPICON_NAMES` in the Runner
/// target; the green palette uses the primary icon. iOS always confirms a
/// change with its own alert, so the native side skips the call when the
/// icon already matches. Android keeps the green icon.
class AppIconService {
  static const _channel = MethodChannel('nudge/app_icon');

  /// The alternate icon for [palette], or null for the primary icon.
  static String? iconName(AppPalette palette) =>
      palette == AppPalette.meadow ? null : 'AppIcon-${palette.name}';

  Future<void> apply(AppPalette palette) async {
    if (!Platform.isIOS) return;
    try {
      await _channel.invokeMethod<bool>('setIcon', iconName(palette));
    } catch (_) {
      // Cosmetic only: a failed switch leaves the previous icon.
    }
  }
}
